import {load,save,flush,backupProject,readPreviousWorkspace} from './storage.js';
import {installRequestedIdeas} from './add-project-ideas.js';
import {installRequestedCompaction} from './compact-project-ideas.js';
import {installOperations} from './project-operation.js';
import {createExplorer} from './explorer-ui.js';
import {nodeSearchText,normalizeExplorer,sectionKeys,categories} from './explorer-model.js';
const $=(s)=>document.querySelector(s), app=$('#app');
const colorChoices=[...categories,['Âmbar','#e8a43b'],['Rosa suave','#e37589'],['Cinza','#8792aa']];const palette=colorChoices.map(([,color])=>color);
const paths={plus:'M12 5v14M5 12h14',back:'M15 18l-6-6 6-6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',moon:'M20 15a9 9 0 0 1-11-11 9 9 0 1 0 11 11',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',undo:'M9 4L4 9l5 5M4 9h9a7 7 0 0 1 0 14',redo:'M15 4l5 5-5 5M20 9h-9a7 7 0 0 0 0 14',center:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',link:'M9 15l6-6M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 17v4h16v-4',check:'M5 12l4 4L19 6',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'M6 6l12 12M18 6L6 18',minus:'M5 12h14',copy:'M8 8h13v13H8zM16 8V3H3v13h5',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-5'};
const ico=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.plus}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();let data={projects:[],theme:'light'},project=null,selection=null,edgeSelection=null,connecting=null,history=[],future=[],homeQuery='',nodeQuery='',drag=null,readonly=false,status='Tudo salvo neste navegador';
const explorer=createExplorer({project:()=>project,selection:()=>selection,readonly:()=>readonly,esc,changed,mutate,checkpoint,renderMap,applyView,center,toast});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function persist(){if(readonly)return;save(data,s=>{status=s;const el=$('.save-state');if(el)el.textContent=s;if(s.startsWith('Falha'))toast(s);});}
function checkpoint(){history.push(structuredClone(project));if(history.length>80)history.shift();future=[];}
function changed(){project.updated=Date.now();persist();updateUndo();}
function mutate(fn){if(readonly){toast('Este mapa está aberto em outra aba. Use a primeira aba para editar.');return;}checkpoint();fn();changed();renderMap();}
function updateUndo(){const a=$('#undo'),b=$('#redo');if(a)a.disabled=!history.length;if(b)b.disabled=!future.length;}
function btn(id,icon,label,extra=''){return `<button id="${id}" class="icon ${extra}" title="${label}" aria-label="${label}">${ico(icon)}</button>`;}
function theme(){document.body.classList.toggle('dark',data.theme==='dark');}
function toggleTheme(){data.theme=data.theme==='dark'?'light':'dark';theme();persist();if(project)renderEditor();else renderHome();}
function date(t){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(t);}
function bounds(p){if(!p.nodes.length)return {x:0,y:0,w:600,h:400};const x=Math.min(...p.nodes.map(n=>n.x)),y=Math.min(...p.nodes.map(n=>n.y));return{x,y,w:Math.max(...p.nodes.map(n=>n.x+210))-x,h:Math.max(...p.nodes.map(n=>n.y+100))-y};}
function curve(a,b,direction){const left=direction==='left';const ax=left?a.x:a.x+210,ay=a.y+43,bx=left?b.x+210:b.x,by=b.y+43;const d=Math.max(65,Math.abs(bx-ax)/2)*(left?-1:1);return `M${ax} ${ay} C${ax+d} ${ay} ${bx-d} ${by} ${bx} ${by}`;}
function thumbnail(p){const b=bounds(p),pad=60;return `<svg viewBox="${b.x-pad} ${b.y-pad} ${b.w+pad*2} ${b.h+pad*2}" aria-hidden="true">${p.edges.map(e=>{const a=p.nodes.find(n=>n.id===e.source),c=p.nodes.find(n=>n.id===e.target);return a&&c?`<path d="${curve(a,c,e.direction)}" fill="none" stroke="#b6b9d0" stroke-width="3"/>`:'';}).join('')}${p.nodes.map((n,i)=>`<rect x="${n.x}" y="${n.y+10}" width="210" height="65" rx="12" fill="${i===0?n.color:'#ffffff'}" stroke="${n.color}" stroke-width="3"/><text x="${n.x+105}" y="${n.y+48}" text-anchor="middle" font-size="17" font-family="Segoe UI,sans-serif" fill="${i===0?'white':'#35394b'}">${esc(n.text.slice(0,22))}</text>`).join('')}</svg>`;}
function renderHome(){project=null;selection=null;edgeSelection=null;history=[];future=[];app.innerHTML=`${readonly?'<div class="readonly">Aberto em outra aba. Esta aba está em modo de leitura.</div>':''}<header><div class="brand"><img src="favicon.svg" alt="">nexo<small>ESPAÇO PARA SUAS IDEIAS</small></div><div class="actions"><button id="importBtn" class="header-import">${ico('upload')}<span>Importar JSON</span></button><button id="restoreBackup" title="Recuperar a versão anterior salva">Restaurar backup</button>${btn('theme',data.theme==='dark'?'sun':'moon','Alternar tema')}${btn('help','help','Atalhos e ajuda')}</div></header><main class="home"><div class="eyebrow">SEU ESPAÇO DE TRABALHO</div><div class="home-top"><div><h1>Meus Projetos</h1><p>Um lugar para conectar ideias e tirar planos do papel.</p></div><div class="search">${ico('search')}<input id="projectSearch" placeholder="Buscar projetos" aria-label="Buscar projetos" value="${esc(homeQuery)}"></div></div><div class="section-label"><span id="count"></span><span>Última edição primeiro</span></div><div class="grid" id="cards"></div><div class="local-note">${ico('shield')}<span>Salvo automaticamente neste navegador. Exporte um JSON para guardar uma cópia dos seus projetos.</span></div></main>`;renderCards();$('#projectSearch').oninput=e=>{homeQuery=e.target.value;renderCards();};$('#importBtn').onclick=()=>$('#import').click();$('#restoreBackup').onclick=restoreBackup;$('#theme').onclick=toggleTheme;$('#help').onclick=help;}
function renderCards(){const projects=[...data.projects].sort((a,b)=>b.updated-a.updated).filter(p=>p.name.toLowerCase().includes(homeQuery.toLowerCase()));$('#count').textContent=`${data.projects.length} projeto${data.projects.length!==1?'s':''}`;$('#cards').innerHTML=projects.map(p=>`<article class="card"><button class="thumbnail" data-open="${p.id}" aria-label="Abrir ${esc(p.name)}">${thumbnail(p)}</button><div class="card-info"><h2 class="card-title">${esc(p.name)}</h2><div class="card-meta"><span>${p.nodes.length} ideias</span><span>${p.edges.length} conexões</span></div><div class="card-bottom"><span>${date(p.updated)}</span><button data-open="${p.id}">Abrir projeto</button></div></div><details class="card-menu"><summary aria-label="Opções de ${esc(p.name)}">···</summary><div class="menu"><button data-action="rename" data-id="${p.id}">Renomear</button><button data-action="duplicate" data-id="${p.id}">Duplicar projeto</button><button data-action="export" data-id="${p.id}">Exportar JSON</button><button class="danger" data-action="delete" data-id="${p.id}">Excluir projeto</button></div></details></article>`).join('')+`<button class="new-card" id="newProject"><span class="plus">+</span><strong>Novo projeto</strong><span>Dê espaço à sua próxima ideia</span></button>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openProject(b.dataset.open));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{b.closest('details').open=false;projectAction(b.dataset.action,b.dataset.id);});$('#newProject').onclick=newProject;}
async function ask(title,value=''){return new Promise(resolve=>{const d=document.createElement('dialog');d.innerHTML=`<form><h2>${esc(title)}</h2><label for="dialogName">Nome do projeto</label><input id="dialogName" value="${esc(value)}" maxlength="120" required autocomplete="off"><div class="actions"><button type="button" class="cancel">Cancelar</button><button class="primary" type="submit">Salvar</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('input').select();d.querySelector('form').onsubmit=e=>{e.preventDefault();const value=d.querySelector('input').value.trim();if(value){d.close();d.remove();resolve(value);}};const cancel=()=>{d.remove();resolve(null);};d.querySelector('.cancel').onclick=cancel;d.oncancel=cancel;});}
async function confirmDelete(title,body){return new Promise(resolve=>{const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(body)}</p><div class="actions"><button id="cancelDelete">Cancelar</button><button id="confirmDelete" class="danger">Excluir</button></div>`;document.body.append(d);d.showModal();d.querySelector('#cancelDelete').onclick=()=>{d.remove();resolve(false);};d.querySelector('#confirmDelete').onclick=()=>{d.remove();resolve(true);};d.oncancel=()=>{d.remove();resolve(false);};});}
async function restoreBackup(){if(readonly)return toast('Edite na primeira aba.');try{await flush();const previous=await readPreviousWorkspace();if(!previous?.projects)return toast('Ainda não há uma versão anterior disponível.');const d=document.createElement('dialog');d.innerHTML='<h2>Recuperar versão anterior?</h2><p>A versão anterior será adicionada como cópias dos projetos. Seus projetos atuais continuam disponíveis.</p><div class="actions"><button class="cancel">Cancelar</button><button class="primary">Recuperar cópias</button></div>';document.body.append(d);d.showModal();d.querySelector('.cancel').onclick=()=>d.close();d.onclose=()=>d.remove();d.querySelector('.primary').onclick=()=>{for(const p of previous.projects){const copy=structuredClone(p);copy.id=uid();copy.name=copy.name.slice(0,106)+' (recuperado)';copy.updated=Date.now();data.projects.push(copy);}persist();d.close();renderHome();toast('Versão anterior recuperada como cópias.');};}catch{toast('Não foi possível ler o backup local. Importe um JSON se tiver uma cópia.');}}
async function newProject(){if(readonly)return toast('Edite na primeira aba do Nexo.');const name=await ask('Novo projeto');if(!name)return;const p={id:uid(),name,updated:Date.now(),nodes:[{id:uid(),text:name,notes:'',x:0,y:0,color:palette[0]}],edges:[],view:{x:0,y:0,z:1}};data.projects.push(p);persist();openProject(p.id,true);}
async function projectAction(action,id){const p=data.projects.find(p=>p.id===id);if(!p)return;if(action==='export')return exportJSON(p);if(readonly)return toast('Edite na primeira aba do Nexo.');if(action==='rename'){const name=await ask('Renomear projeto',p.name);if(name){p.name=name;p.updated=Date.now();}}if(action==='duplicate'){const copy=structuredClone(p);copy.id=uid();copy.name=copy.name.slice(0,112)+' (cópia)';copy.updated=Date.now();data.projects.push(copy);}if(action==='delete'){if(!await confirmDelete('Excluir projeto?',`“${p.name}” será excluído deste navegador. Exporte um JSON antes de continuar se quiser guardar uma cópia.`))return;data.projects=data.projects.filter(x=>x.id!==id);}persist();renderHome();}
function openProject(id,fit=false){project=data.projects.find(p=>p.id===id);if(!project)return;selection=null;edgeSelection=null;connecting=null;nodeQuery='';history=[];future=[];normalizeExplorer(project);renderEditor();if(fit)center();}
function renderEditor(){app.innerHTML=`<div class="editor">${readonly?'<div class="readonly">Modo de leitura · edite na primeira aba</div>':''}<header><div class="actions">${btn('back','back','Voltar aos projetos')}<img src="favicon.svg" width="26" height="26" alt="Nexo"><span class="project-title">${esc(project.name)}</span></div><span class="save-state" role="status">${esc(status)}</span><div class="actions"><details class="export-menu"><summary>Exportar</summary><div class="menu"><button id="exportJSON" aria-label="Backup JSON">${ico('download')}Backup JSON</button><button id="exportPNG" aria-label="Imagem PNG">${ico('download')}Imagem PNG</button></div></details>${btn('theme',data.theme==='dark'?'sun':'moon','Alternar tema')}${btn('help','help','Atalhos e ajuda')}</div></header><div class="workspace" id="canvas"><div class="world" id="world"><svg class="edges" id="edges"></svg><div id="nodes"></div></div><nav class="toolbar" aria-label="Ferramentas do mapa">${btn('add','plus','Adicionar ideia (N)')}${btn('connect','link','Conectar ideias (C)')}<div class="separator"></div>${btn('undo','undo','Desfazer (Ctrl Z)')}${btn('redo','redo','Refazer (Ctrl Shift Z)')}<div class="separator"></div>${btn('center','center','Centralizar mapa (F)')}${btn('delete','trash','Excluir seleção (Delete)')}</nav><div class="search canvas-search">${ico('search')}<input id="nodeSearch" aria-label="Buscar ideias" placeholder="Buscar no mapa…" value="${esc(nodeQuery)}"><div id="results" class="results" hidden></div></div><div id="inspector"></div><div class="map-hint">Arraste o fundo para mover · Scroll para zoom · Tab para criar uma ideia filha</div><div class="zoom">${btn('zoomOut','minus','Diminuir zoom')}<span id="zoomLabel">100%</span>${btn('zoomIn','plus','Aumentar zoom')}${btn('fit','center','Ajustar mapa')}</div></div></div>`;$('#back').onclick=()=>{flush();renderHome();};$('#add').onclick=()=>addNode();$('#connect').onclick=startConnection;$('#undo').onclick=undo;$('#redo').onclick=redo;$('#center').onclick=center;$('#fit').onclick=center;$('#delete').onclick=deleteSelection;$('#theme').onclick=toggleTheme;$('#help').onclick=help;$('#exportJSON').onclick=()=>exportJSON(project);$('#exportPNG').onclick=exportPNG;$('#zoomIn').onclick=()=>zoom(1.2);$('#zoomOut').onclick=()=>zoom(1/1.2);$('#nodeSearch').oninput=e=>{nodeQuery=e.target.value;renderResults();};const canvas=$('#canvas');canvas.onpointerdown=pointerDown;canvas.onpointermove=pointerMove;canvas.onpointerup=pointerUp;canvas.onpointercancel=pointerUp;canvas.addEventListener('wheel',wheel,{passive:false});canvas.ondblclick=e=>{if(e.target===canvas){const p=point(e);addNode(null,p);}};explorer.mount();renderMap();}
function applyView(){const v=project.view;$('#world').style.transform=`translate(${v.x}px,${v.y}px) scale(${v.z})`;$('#zoomLabel').textContent=`${Math.round(v.z*100)}%`;$('#canvas').style.backgroundPosition=`${v.x}px ${v.y}px`;$('#canvas').style.backgroundSize=`${22*v.z}px ${22*v.z}px`;explorer.renderMinimap();}
function renderMap(){if(!project||!$('#world'))return;const visible=explorer.visibleIds();if(selection&&!visible.has(selection))selection=null;$('#nodes').innerHTML=project.nodes.filter(n=>visible.has(n.id)).map((n,i)=>`<div class="node ${selection===n.id?'selected':''} ${n.id===project.nodes[0]?.id?'root':''} ${n.notes?'has-notes':''}" role="button" tabindex="0" aria-label="${esc(n.text)}, editar ideia" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px;--node-color:${n.color};${n.id===project.nodes[0]?.id?`background:${n.color};border-color:${n.color}`:''}"><div class="node-label">${esc(n.text)}</div><button class="node-add" data-child="${n.id}" aria-label="Criar ideia filha" title="Criar filha (Tab)">+</button></div>`).join('');renderEdges();applyView();renderInspector();explorer.enhanceInspector();explorer.render();updateUndo();$('#connect').style.color=connecting?'var(--accent)':'';}
function renderEdges(){const svg=$('#edges');const visible=explorer.visibleIds(),byId=new Map(project.nodes.map(n=>[n.id,n]));svg.innerHTML=project.edges.filter(e=>visible.has(e.source)&&visible.has(e.target)).map(e=>{const a=byId.get(e.source),b=byId.get(e.target);return a&&b?`<path class="edge ${edgeSelection===e.id?'selected':''}" data-edge="${e.id}" d="${curve(a,b,e.direction)}"/><path data-edge="${e.id}" d="${curve(a,b,e.direction)}" fill="none" stroke="transparent" stroke-width="18" style="pointer-events:stroke;cursor:pointer"/>`:'';}).join('');}
function renderInspector(){const holder=$('#inspector');const n=project.nodes.find(n=>n.id===selection);if(!n){holder.innerHTML=edgeSelection?`<aside class="inspector"><div class="inspector-head"><strong>Conexão</strong>${btn('closeInspector','close','Fechar')}</div><p class="muted">Linha selecionada</p><button id="removeEdge" class="danger">${ico('trash')}Excluir conexão</button></aside>`:'';if(edgeSelection){$('#removeEdge').onclick=deleteSelection;$('#closeInspector').onclick=clearSelection;}return;}holder.innerHTML=`<aside class="inspector"><div class="inspector-head"><strong>Detalhes da ideia</strong>${btn('closeInspector','close','Fechar detalhes')}</div>${connecting?'<span class="badge">Clique na ideia que deseja conectar</span>':''}<label for="nodeText">Ideia</label><textarea id="nodeText" rows="2" maxlength="500" ${readonly?'readonly':''}>${esc(n.text)}</textarea><label for="nodeNotes">Anotações <span class="muted">· opcional</span></label><textarea id="nodeNotes" rows="5" maxlength="100000" placeholder="Detalhes, referências, próximos passos…" ${readonly?'readonly':''}>${esc(n.notes)}</textarea><label>Cor</label><div class="colors">${palette.map((c,i)=>`<button class="color ${n.color===c?'active':''}" data-color="${c}" style="--color:${c}" aria-label="Cor ${colorChoices[i][0]}"></button>`).join('')}</div><div class="actions"><button id="child">${ico('plus')}Ideia filha <kbd>Tab</kbd></button><button id="linkNode">${ico('link')}Conectar</button><button id="deleteNode" class="danger">${ico('trash')}Excluir</button></div></aside>`;$('#closeInspector').onclick=clearSelection;let editing=false;const edit=(e,key)=>{if(readonly)return;if(!editing){checkpoint();editing=true;}n[key]=e.target.value;const el=document.querySelector(`[data-node="${n.id}"]`);el.querySelector('.node-label').textContent=n.text;el.classList.toggle('has-notes',!!n.notes);changed();};$('#nodeText').oninput=e=>edit(e,'text');$('#nodeNotes').oninput=e=>edit(e,'notes');$('#nodeText').onblur=$('#nodeNotes').onblur=()=>editing=false;document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>mutate(()=>n.color=b.dataset.color));$('#child').onclick=()=>addNode(n.id);$('#linkNode').onclick=startConnection;$('#deleteNode').onclick=deleteSelection;}
function clearSelection(){selection=null;edgeSelection=null;connecting=null;renderMap();}
function selectNode(id){if(connecting&&id!==connecting){const source=connecting;connecting=null;mutate(()=>{if(!project.edges.some(e=>e.source===source&&e.target===id||e.source===id&&e.target===source))project.edges.push({id:uid(),source,target:id});selection=id;});return;}selection=id;edgeSelection=null;renderMap();}
function startConnection(){if(!selection)return toast('Selecione uma ideia e depois clique em Conectar.');connecting=connecting?null:selection;renderMap();if(connecting)toast('Clique em outra ideia para criar a conexão.');}
function point(e){const r=$('#canvas').getBoundingClientRect(),v=project.view;return{x:(e.clientX-r.left-v.x)/v.z,y:(e.clientY-r.top-v.y)/v.z};}
function addNode(parentId=null,pos=null){if(readonly)return toast('Edite na primeira aba.');const parent=project.nodes.find(n=>n.id===parentId);if(!pos){const r=$('#canvas').getBoundingClientRect();pos=parent?{x:parent.x+290,y:parent.y+project.edges.filter(e=>e.source===parent.id).length*125}:{x:(r.width/2-project.view.x)/project.view.z-105,y:(r.height/2-project.view.y)/project.view.z-42};}while(project.nodes.some(n=>Math.abs(n.x-pos.x)<220&&Math.abs(n.y-pos.y)<100))pos.y+=125;const n={id:uid(),text:'Nova ideia',notes:'',x:pos.x,y:pos.y,color:parent?.color||palette[0]};mutate(()=>{project.nodes.push(n);if(parent)project.edges.push({id:uid(),source:parent.id,target:n.id});selection=n.id;edgeSelection=null;explorer.reveal(n.id,false);});focusNode(n);$('#nodeText')?.focus();$('#nodeText')?.select();}
function deleteSelection(){if(!selection&&!edgeSelection)return;mutate(()=>{if(selection){project.nodes=project.nodes.filter(n=>n.id!==selection);project.edges=project.edges.filter(e=>e.source!==selection&&e.target!==selection);}else project.edges=project.edges.filter(e=>e.id!==edgeSelection);selection=null;edgeSelection=null;connecting=null;});}
function restore(p){const index=data.projects.findIndex(x=>x.id===project.id);project=p;data.projects[index]=p;selection=null;edgeSelection=null;changed();renderMap();}
function undo(){if(readonly||!history.length)return;future.push(structuredClone(project));restore(history.pop());}
function redo(){if(readonly||!future.length)return;history.push(structuredClone(project));restore(future.pop());}
function pointerDown(e){if(e.button!==0)return;if(e.target.closest('button,input,textarea,nav,.inspector,.search,.zoom,.explorer-tools,.minimap-box,.compare-tray,.focus-banner')){const child=e.target.closest('[data-child]');if(child){e.preventDefault();addNode(child.dataset.child);}return;}const node=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]');if(edge){edgeSelection=edge.dataset.edge;selection=null;connecting=null;renderMap();return;}if(node){const id=node.dataset.node;if(connecting){selectNode(id);return;}selectNode(id);if(readonly)return;const n=project.nodes.find(n=>n.id===id);drag={kind:'node',id,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,moved:false};}else{selection=null;edgeSelection=null;connecting=null;renderMap();drag={kind:'pan',startX:e.clientX,startY:e.clientY,x:project.view.x,y:project.view.y,moved:false};}$('#canvas').setPointerCapture(e.pointerId);}
function pointerMove(e){if(!drag)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(!drag.moved&&Math.hypot(dx,dy)<4)return;if(!drag.moved&&drag.kind==='node')checkpoint();drag.moved=true;if(drag.kind==='pan'){project.view.x=drag.x+dx;project.view.y=drag.y+dy;applyView();}else{const n=project.nodes.find(n=>n.id===drag.id);n.x=drag.x+dx/project.view.z;n.y=drag.y+dy/project.view.z;const el=document.querySelector(`[data-node="${n.id}"]`);el.style.left=n.x+'px';el.style.top=n.y+'px';renderEdges();explorer.renderMinimap();}changed();}
function pointerUp(e){if(!drag)return;const d=drag;drag=null;if($('#canvas').hasPointerCapture(e.pointerId))$('#canvas').releasePointerCapture(e.pointerId);if(d.kind==='node'&&!d.moved){$('#nodeText')?.focus();}if(d.moved)flush();}
function setZoom(z,cx,cy){const v=project.view,newZ=Math.max(.15,Math.min(3,z));const px=(cx-v.x)/v.z,py=(cy-v.y)/v.z;v.x=cx-px*newZ;v.y=cy-py*newZ;v.z=newZ;applyView();changed();}
function zoom(factor){const r=$('#canvas').getBoundingClientRect();setZoom(project.view.z*factor,r.width/2,r.height/2);}
function wheel(e){if(e.target.closest('.inspector,.results,.explorer-tools,.comparison-scroll'))return;e.preventDefault();const r=$('#canvas').getBoundingClientRect();setZoom(project.view.z*Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);}
function center(){const visible=explorer.visibleIds();const b=bounds({nodes:project.nodes.filter(n=>visible.has(n.id))}),r=$('#canvas').getBoundingClientRect();const z=Math.max(.15,Math.min(1.15,(r.width-180)/(b.w+160),(r.height-160)/(b.h+100)));project.view={x:(r.width-b.w*z)/2-b.x*z,y:(r.height-b.h*z)/2-b.y*z,z};applyView();changed();}
function focusNode(n){const r=$('#canvas').getBoundingClientRect(),v=project.view;v.z=Math.max(.7,v.z);const panel=document.querySelector('.inspector'),available=r.width-(panel&&r.width>700?panel.getBoundingClientRect().width+24:0);v.x=available/2-(n.x+105)*v.z;v.y=r.height/2-(n.y+43)*v.z;applyView();changed();}
function renderResults(){const el=$('#results');el.hidden=!nodeQuery.trim();const q=nodeQuery.toLocaleLowerCase();const matches=project.nodes.filter(n=>nodeSearchText(n).includes(q));el.innerHTML=matches.length?matches.map(n=>`<button data-result="${n.id}">${esc(n.text||'Ideia sem título')}</button>`).join(''):'<div class="empty">Nenhuma ideia encontrada</div>';el.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const n=project.nodes.find(n=>n.id===b.dataset.result);selection=n.id;edgeSelection=null;explorer.reveal(n.id);renderMap();focusNode(n);const result=document.querySelector('[data-node="'+n.id+'"]');result?.classList.add('search-hit');setTimeout(()=>result?.classList.remove('search-hit'),1800);el.hidden=true;});}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function filename(name){return name.replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').slice(0,100)||'projeto';}
function exportJSON(p){download(new Blob([JSON.stringify({format:'nexo',version:1,exportedAt:new Date().toISOString(),projects:[structuredClone(p)]},null,2)],{type:'application/json'}),filename(p.name)+'.json');toast('Backup JSON exportado.');}
function validateImport(raw){if(raw?.format!=='nexo'||raw.version!==1||!Array.isArray(raw.projects)||raw.projects.length>100)throw Error('Arquivo incompatível. Escolha um backup JSON do Nexo.');return raw.projects.map(p=>{if(!p||typeof p.name!=='string'||!p.name.trim()||p.name.length>120||!Array.isArray(p.nodes)||p.nodes.length>5000||!Array.isArray(p.edges)||p.edges.length>10000)throw Error('Projeto inválido ou acima do limite de importação.');const ids=new Set();const nodes=p.nodes.map(n=>{if(!n||typeof n.id!=='string'||! /^[a-z0-9_-]{1,150}$/i.test(n.id)||ids.has(n.id)||typeof n.text!=='string'||n.text.length>500||typeof n.notes!=='string'||n.notes.length>100000||!Number.isFinite(n.x)||!Number.isFinite(n.y)||Math.abs(n.x)>1e7||Math.abs(n.y)>1e7||!/^#[0-9a-f]{6}$/i.test(n.color))throw Error('Bloco inválido no backup.');ids.add(n.id);const sections={},review={};for(const key of sectionKeys){if(n.sections?.[key]!==undefined){if(typeof n.sections[key]!=='string'||n.sections[key].length>20000)throw Error('Seção inválida');sections[key]=n.sections[key];}}for(const key of ['audience','validation']){if(n.review?.[key]!==undefined){if(typeof n.review[key]!=='string'||n.review[key].length>10000)throw Error('Critério inválido');review[key]=n.review[key];}}if(n.review?.difficulty!==undefined){if(!['Não estimada','Baixa','Média','Alta'].includes(n.review.difficulty))throw Error('Dificuldade inválida');review.difficulty=n.review.difficulty;}return{id:n.id,text:n.text,notes:n.notes,x:n.x,y:n.y,color:n.color,...(n.favorite?{favorite:true}:{}),...(Object.keys(sections).length?{sections}:{}),...(Object.keys(review).length?{review}:{})};});const edgeIds=new Set();const edges=p.edges.map(e=>{if(!e||typeof e.id!=='string'||! /^[a-z0-9_-]{1,150}$/i.test(e.id)||edgeIds.has(e.id)||!ids.has(e.source)||!ids.has(e.target)||e.source===e.target)throw Error('Conexão inválida no backup.');edgeIds.add(e.id);if(e.direction!==undefined&&!['left','right'].includes(e.direction))throw Error('Direção de conexão inválida');return{id:e.id,source:e.source,target:e.target,...(e.direction?{direction:e.direction}:{})};});const v=p.view;if(!v||![v.x,v.y,v.z].every(Number.isFinite)||v.z<.15||v.z>3||Math.abs(v.x)>1e8||Math.abs(v.y)>1e8)throw Error('Posição do mapa inválida.');const imported={id:uid(),name:p.name,updated:Number.isFinite(p.updated)?p.updated:Date.now(),nodes,edges,view:{x:v.x,y:v.y,z:v.z},explorer:p.explorer,presentationIds:Array.isArray(p.presentationIds)?[...new Set(p.presentationIds.filter(id=>ids.has(id)))]:[]};normalizeExplorer(imported);return imported;});}
$('#import').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(readonly)return toast('Importe na primeira aba.');try{if(file.size>20e6)throw Error('O arquivo excede o limite de 20 MB.');const projects=validateImport(JSON.parse(await file.text()));data.projects.push(...projects);persist();renderHome();toast(`${projects.length} projeto(s) importado(s). Os projetos existentes foram preservados.`);}catch(err){toast(err.message);}};
async function exportPNG(){const p=project,b=bounds(p),pad=55,scale=Math.min(2,6000/(b.w+pad*2),6000/(b.h+pad*2));const canvas=document.createElement('canvas');canvas.width=Math.ceil((b.w+pad*2)*scale);canvas.height=Math.ceil((b.h+pad*2)*scale);const c=canvas.getContext('2d');c.fillStyle=data.theme==='dark'?'#141823':'#f5f6fa';c.fillRect(0,0,canvas.width,canvas.height);c.scale(scale,scale);c.translate(pad-b.x,pad-b.y);c.strokeStyle='#a9afc6';c.lineWidth=2;for(const e of p.edges){const a=p.nodes.find(n=>n.id===e.source),t=p.nodes.find(n=>n.id===e.target);if(a&&t)c.stroke(new Path2D(curve(a,t,e.direction)));}p.nodes.forEach((n,i)=>{c.fillStyle=i===0?n.color:(data.theme==='dark'?'#202635':'white');c.strokeStyle=n.color;c.beginPath();c.roundRect(n.x,n.y,210,90,12);c.fill();c.stroke();c.fillStyle=i===0?'white':(data.theme==='dark'?'#edf0fa':'#252b3d');c.font='15px Segoe UI, sans-serif';const words=n.text.split(/\s+/);let line='',lines=[];for(const word of words){if(c.measureText(line+' '+word).width>173&&line){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);lines.slice(0,3).forEach((l,j)=>{while(c.measureText(l).width>173)l=l.slice(0,-1);c.fillText(l,n.x+17,n.y+28+j*21);});});canvas.toBlob(blob=>{if(blob){download(blob,filename(p.name)+'.png');toast('Imagem PNG exportada.');}else toast('Não foi possível exportar a imagem.');},'image/png');}
function help(){const d=document.createElement('dialog');d.innerHTML=`${btn('closeHelp','close','Fechar ajuda','dialog-close')}<h2>Ideias no seu ritmo</h2><p>Clique em um bloco para editar. Arraste-o para organizar. Arraste o fundo para navegar e use o scroll para aproximar. Clique em Conectar e escolha outra ideia.</p><div class="keys"><span>Pesquisar ideias / projetos</span><kbd>Ctrl / ⌘ F</kbd><span>Salvar agora</span><kbd>Ctrl / ⌘ S</kbd><span>Nova ideia filha</span><kbd>Tab</kbd><span>Nova ideia</span><kbd>N</kbd><span>Conectar seleção</span><kbd>C</kbd><span>Centralizar mapa</span><kbd>F</kbd><span>Excluir seleção</span><kbd>Delete</kbd><span>Desfazer</span><kbd>Ctrl / ⌘ Z</kbd><span>Refazer</span><kbd>Ctrl / ⌘ Shift Z</kbd><span>Fechar seleção</span><kbd>Esc</kbd></div><p>Os atalhos de letras funcionam fora dos campos de texto. Tab cria uma filha quando o bloco está selecionado e o foco está no mapa ou no título da ideia. Duplo clique no fundo também cria uma ideia.</p><p>Use o pequeno botão −/+ de cada ramo para recolher ou expandir. Em Visualização, filtre por categoria ou favoritos. Nos detalhes, foque um ramo, marque favoritos e selecione até três ideias para comparar. O minimapa permite navegar com um clique. A busca também encontra ideias escondidas e reabre o caminho até elas.</p><p><strong>Seus dados ficam neste navegador.</strong> Limpar os dados do site ou usar uma janela privada pode apagar os projetos. Use Exportar JSON para guardar um backup. Não há login nem sincronização.</p>`;document.body.append(d);d.showModal();$('#closeHelp').onclick=()=>d.remove();d.oncancel=()=>d.remove();}
document.addEventListener('keydown',e=>{if($('dialog[open]'))return;if(e.key==='Escape'){document.querySelectorAll('details[open]').forEach(d=>d.open=false);$('#results')?.setAttribute('hidden','');}const typing=e.target.matches('input,textarea,select,[contenteditable="true"]');if(e.key==='Escape'&&project){clearSelection();return;}if(project && e.key==='Tab' && selection && e.target.id==='nodeText'){e.preventDefault();addNode(selection);return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='f'&&!typing){e.preventDefault();const input=project?$('#nodeSearch'):$('#projectSearch');input?.focus();input?.select();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();flush().then(()=>toast(status));return;}if(!project||typing)return;if((e.key==='Enter'||e.key===' ')&&e.target.closest('[data-node]')&&!e.target.closest('button')){e.preventDefault();selectNode(e.target.closest('[data-node]').dataset.node);$('#nodeText')?.focus();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return;}if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Tab'&&selection&&(e.target===document.body||e.target.closest('[data-node]')||e.target===$('#canvas'))){e.preventDefault();addNode(selection);}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();}if(e.key.toLowerCase()==='n')addNode();if(e.key.toLowerCase()==='c')startConnection();if(e.key.toLowerCase()==='f')center();});
function example(){const p={id:uid(),name:'Comparador de Preços',updated:Date.now(),nodes:[],edges:[],view:{x:110,y:170,z:.72}};const root={id:uid(),text:'Comparador de Preços',notes:'Compare preços, acompanhe o histórico e encontre boas oportunidades.',x:0,y:225,color:palette[0]};p.nodes.push(root);const groups=[['Front-end',palette[1],['Página inicial','Pesquisa de produtos','Histórico de preços']],['Back-end',palette[2],['API','Banco de dados','Web scraping']],['Monetização',palette[3],['Amazon Afiliados','Mercado Livre','Shopee']]];groups.forEach(([text,color,children],i)=>{const n={id:uid(),text,notes:'',x:310,y:i*275,color};p.nodes.push(n);p.edges.push({id:uid(),source:root.id,target:n.id});children.forEach((text,j)=>{const child={id:uid(),text,notes:'',x:620,y:i*275+(j-1)*85,color};p.nodes.push(child);p.edges.push({id:uid(),source:n.id,target:child.id});});});return p;}
async function init(){try{if(navigator.locks){await new Promise(resolve=>{navigator.locks.request('nexo-editor',{ifAvailable:true},async lock=>{readonly=!lock;resolve();if(lock)await new Promise(()=>{});}).catch(()=>resolve());});}const stored=await load();if(stored)data=stored;else if(!readonly){data.projects=[example()];persist();}let addition=null;if(!readonly){try{addition=await installRequestedIdeas(data,backupProject);const compacted=await installRequestedCompaction(data,backupProject);if(compacted)addition=compacted;const operationsAdded=await installOperations(data,backupProject);if(operationsAdded){persist();await flush();}if(addition){persist();await flush();}}catch(err){toast('A adição não foi concluída. Seus projetos existentes foram preservados.');}}theme();renderHome();if(addition){openProject(addition.projectId);selection=addition.root.id;project.view.z=.85;renderMap();focusNode(addition.root);toast(addition.message||`${addition.projects} projetos e ${addition.features} funcionalidades adicionados.`);}if(navigator.storage?.persist&&!readonly)navigator.storage.persist().catch(()=>{});if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'list_projects',description:'Lista os projetos locais do Nexo sem alterar dados.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Entrada inválida');return{projects:data.projects.map(p=>({id:p.id,name:p.name,ideas:p.nodes.length,updated:p.updated}))};}});}catch{}}}catch(err){app.innerHTML=`<main class="home"><h1>Não foi possível abrir seus projetos</h1><p>O armazenamento local está indisponível. Seus dados não foram substituídos.</p><button id="retry">Tentar novamente</button><p class="muted">Verifique se o navegador permite armazenar dados para este site.</p></main>`;$('#retry').onclick=()=>location.reload();}}
init();
